declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    cyclicExecution : BOOL;
    trigger : BOOL;
    value : LREAL;
    windowSize : INT;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    average : LREAL;
    windowSizeReached : BOOL;
    error : BOOL;
    status : WORD;
END_VAR
VAR
    buf : ARRAY[1..100] OF LREAL;
    cnt : INT;
    head : INT;
    prevTrigger : BOOL;
    trigEdge : BOOL;
    n : INT;
    i : INT;
    idx : INT;
    sum : LREAL;
    take : BOOL;
END_VAR

implementation:
trigEdge := trigger AND NOT prevTrigger;
prevTrigger := trigger;


IF windowSize < 1 OR windowSize > 100 THEN
    error := TRUE;
    status := 16#8200;
ELSE
    error := FALSE;
    status := 16#0000;
END_IF


IF reset THEN
    cnt := 0;
    average := 0.0;
    windowSizeReached := FALSE;
ELSE
    IF NOT error THEN

        take := cyclicExecution OR trigEdge;
        IF take THEN
            head := head + 1;
            IF head > 100 THEN
                head := 1;
            END_IF
            buf[head] := value;
            IF cnt < 100 THEN
                cnt := cnt + 1;
            END_IF
        END_IF


        n := cnt;
        IF n > windowSize THEN
            n := windowSize;
        END_IF
        windowSizeReached := cnt >= windowSize;
        IF n > 0 THEN
            sum := 0.0;
            FOR i := 0 TO n - 1 DO
                idx := head - i;
                IF idx < 1 THEN
                    idx := idx + 100;
                END_IF
                sum := sum + buf[idx];
            END_FOR
            average := sum / n;
        END_IF
    END_IF
END_IF
